 private void customCaptions(){LinearLayout body=vertical();body.setPadding(dp(16),dp(8),dp(16),dp(8));ScrollView scroll=new ScrollView(this);scroll.addView(body);JSONObject c=project.model.caption;select(body,"Font",new TreeSet<>(ATSModel.FONTS).toArray(new String[0]),c.optString("font","Inter Bold"),s->change("caption_style","font",s,false));fontSizeSlider(body,c.optInt("size",100));select(body,"Background",new String[]{"Dark Brush","None","Paper","Shadow Only","Solid Box"},c.optString("background","None"),s->change("caption_style","background",s,false));select(body,"Maximum lines",new String[]{"1","2"},String.valueOf(c.optInt("max_lines",2)),s->change("caption_style","max_lines",Integer.parseInt(s),false));String[]colors={"#FFFFFF","#FFE600","#00FF57","#FF2D2D","#8A2BE2","#00F0FF","#FF2E97","#111111"};select(body,"Text color",colors,c.optString("text_color","#FFFFFF"),s->change("caption_style","text_color",s,false));select(body,"Accent color",colors,c.optString("accent_color","#FFE600"),s->change("caption_style","accent_color",s,false));if(!Arrays.asList(ATSModel.PRESETS).subList(0,6).contains(c.optString("preset","Minimal Cinematic")))select(body,"Animation",new String[]{"FADE","POP","NONE"},c.optString("animation","FADE"),s->change("caption_style","animation",s,false));new AlertDialog.Builder(this).setTitle("Caption customization").setView(scroll).setPositiveButton("Done",null).show();}
 private void prepareAudio(boolean playWhenReady){if(project.model==null||project.narration==null)return;pause();audioCancel.set(true);audioCancel=new AtomicBoolean();AtomicBoolean token=audioCancel;int version=++revision;Project snapshot;try{snapshot=new Project(new MediaFiles(this));snapshot.load(project.save().toString());}catch(Exception e){failure(e);return;}mixing=true;playAfterPrepare=playWhenReady;if(play!=null){play.setText("…");play.setEnabled(false);}File parent=new File(getCacheDir(),"preview-jobs"),job=new File(parent,"mix-"+version+"-"+System.currentTimeMillis());job.mkdirs();new Thread(()->{try{File wav=AudioEngine.mix(this,snapshot,job,token,(s,x)->{});handler.post(()->{if(version!=revision||token.get()){try{MediaFiles.clean(job,parent);}catch(Exception ignored){}return;}try{if(player!=null)player.release();File old=mixed;mixed=wav;JSONObject waves=new JSONObject(read(new File(job,"waveforms.json")));waveform=new float[2][120];for(int ch=0;ch<2;ch++){JSONArray values=waves.getJSONArray(ch==0?"voice":"music");for(int ix=0;ix<120;ix++)waveform[ch][ix]=(float)values.optDouble(ix);}player=new MediaPlayer();player.setDataSource(wav.getPath());player.prepare();player.seekTo((int)(currentFrame*1000L/project.model.fps));player.setOnCompletionListener(mp->{playing=false;if(play!=null)play.setText("▶");});mixing=false;updatePosition();if(play!=null){play.setEnabled(true);play.setText("▶");}if(old!=null&&!old.getParentFile().equals(job))try{MediaFiles.clean(old.getParentFile(),parent);}catch(Exception ignored){}if(playAfterPrepare)togglePlay();}catch(Exception e){failure(e);}});}catch(Exception e){try{MediaFiles.clean(job,parent);}catch(Exception ignored){}handler.post(()->{if(version==revision){mixing=false;if(play!=null){play.setText("▶");play.setEnabled(true);}if(!token.get())failure(e);}});}},"ATS audio preview").start();}
 private void togglePlay(){if(playing){pause();return;}if(player==null||mixing){prepareAudio(true);return;}try{if(currentFrame>=project.model.totalFrames-1){currentFrame=0;player.seekTo(0);}player.start();playing=true;play.setText("Ⅱ");}catch(Exception e){failure(e);}}
 private void pause(){playing=false;playAfterPrepare=false;if(player!=null)try{player.pause();}catch(Exception ignored){}if(play!=null)play.setText("▶");}
 private void updatePosition(){if(project.model==null)return;if(preview!=null)preview.invalidate();if(timeline!=null)timeline.invalidate();if(scrub!=null&&scrub.getProgress()!=currentFrame)scrub.setProgress(currentFrame);if(time!=null)time.setText(clock(currentFrame/(double)project.model.fps)+" / "+clock(project.model.duration));}
 public static String clock(double value){int s=(int)Math.max(0,value);return String.format(Locale.ROOT,"%02d:%02d",s/60,s%60);}
 public final class Preview extends View {
  private Compositor compositor;private Bitmap frame,spare;private int rendered=-1,generation;private boolean busy,released;private String renderError="";private final Paint p=new Paint(3);
  private final java.util.concurrent.ExecutorService queue=java.util.concurrent.Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"ATS preview frames");t.setPriority(Thread.NORM_PRIORITY-1);return t;});
  public Preview(){super(MainActivity.this);setBackground(shape(0xff090c10,18));reset();}
  void reset(){if(released)return;generation++;Compositor old=compositor;if(old!=null)queue.execute(old::close);compositor=new Compositor(MainActivity.this,project.model,project.media);compositor.fit=project.fit;compositor.dates=project.overrides.optBoolean("dates",true);compositor.circles=project.overrides.optBoolean("circles",true);rendered=-1;invalidate();}
  void release(){if(released)return;released=true;generation++;Compositor old=compositor;if(old!=null)queue.execute(old::close);queue.shutdown();if(frame!=null){frame.recycle();frame=null;}if(spare!=null){spare.recycle();spare=null;}}
  private void request(int fw,int fh){if(busy||released)return;busy=true;int target=currentFrame,revision=generation;Compositor renderer=compositor;Bitmap reuse=spare;spare=null;
   queue.execute(()->{Bitmap output=reuse;String error="";try{if(output==null||output.getWidth()!=fw||output.getHeight()!=fh){if(output!=null)output.recycle();output=Bitmap.createBitmap(fw,fh,Bitmap.Config.ARGB_8888);}renderer.render(output,target);}catch(Exception e){error=e.getMessage();}final Bitmap ready=output;final String message=error;handler.post(()->{busy=false;if(released||revision!=generation){if(ready!=null)ready.recycle();if(!released)invalidate();return;}if(message.isEmpty()){Bitmap old=frame;frame=ready;spare=old;rendered=target;renderError="";}else{if(ready!=null)ready.recycle();renderError=message;}invalidate();});});
  }
  protected void onDraw(Canvas c){super.onDraw(c);if(released||project.model==null)return;float ratio=(float)project.model.ratio(),w=Math.min(getWidth()-dp(16),(getHeight()-dp(16))*ratio),h=w/ratio;int fw=Math.max(2,(int)(Math.min(1080,w)/2)*2),fh=Math.max(2,(int)(fw/ratio/2)*2);if(rendered!=currentFrame||frame==null||frame.getWidth()!=fw||frame.getHeight()!=fh)request(fw,fh);RectF r=new RectF((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);if(frame!=null){c.save();Path clip=new Path();clip.addRoundRect(r,dp(12),dp(12),Path.Direction.CW);c.clipPath(clip);c.drawBitmap(frame,null,r,p);c.restore();}else{p.setColor(muted);p.setTextSize(dp(12));c.drawText(renderError.isEmpty()?"Loading preview…":renderError,dp(12),getHeight()/2f,p);}}
 }
 private final class Timeline extends View{Paint p=new Paint(3);Timeline(){super(MainActivity.this);setBackground(shape(panel,12));}protected void onDraw(Canvas c){super.onDraw(c);ATSModel m=project.model;if(m==null)return;float left=dp(72),w=getWidth()-left-dp(10),y=dp(24);p.setTypeface(inter);p.setTextSize(dp(10));p.setColor(muted);c.drawText("Timeline • "+clock(m.duration),dp(10),dp(16),p);String[]names={"Images","Captions","Moments","Voice","Music"};int[]colors={0xff577264,0xff6977b3,0xffe6d23c,0xff7893ab,0xffa29fde};for(int row=0;row<5;row++){float top=y+row*dp(22);p.setColor(muted);c.drawText(names[row],dp(9),top+dp(13),p);p.setColor(0xff242b33);c.drawRoundRect(left,top,left+w,top+dp(14),dp(3),dp(3),p);p.setColor(colors[row]);if(row==0)for(ATSModel.Scene s:m.scenes){RectF box=new RectF(left+w*s.first/m.totalFrames,top,left+w*s.last/m.totalFrames-dp(1),top+dp(20));c.drawRoundRect(box,dp(2),dp(2),p);Bitmap thumb=thumbnails.get(project.media,s.id,()->{if(timeline!=null)timeline.invalidate();});if(thumb!=null&&box.width()>0){int save=c.save();c.clipRect(box);float scale=Math.max(box.width()/thumb.getWidth(),box.height()/thumb.getHeight()),tw=thumb.getWidth()*scale,th=thumb.getHeight()*scale;c.drawBitmap(thumb,null,new RectF(box.centerX()-tw/2,box.centerY()-th/2,box.centerX()+tw/2,box.centerY()+th/2),p);c.restoreToCount(save);}}if(row==1)for(ATSModel.Cue q:m.captions)c.drawRoundRect((float)(left+w*q.start/m.duration),top,(float)(left+w*q.end/m.duration)-1,top+dp(14),dp(2),dp(2),p);if(row==2)for(JSONObject moment:m.moments)c.drawRect(left+w*moment.optInt("_first")/m.totalFrames,top,left+w*moment.optInt("_last")/m.totalFrames,top+dp(14),p);if(row==3||row==4&&project.music!=null){for(int i=0;i<120;i++){float x=left+i*w/120;double wave=waveform==null?0:Math.min(1,waveform[row-3][i]*6);float hh=(float)(dp(12)*wave);c.drawRect(x,top+dp(7)-hh/2,x+Math.max(1,w/160),top+dp(7)+hh/2,p);}}}p.setColor(accent);p.setStrokeWidth(dp(1.5f));float x=left+w*currentFrame/m.totalFrames;c.drawLine(x,y,x,getHeight()-dp(6),p);}public boolean onTouchEvent(android.view.MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN||e.getAction()==MotionEvent.ACTION_MOVE){float left=dp(72),w=getWidth()-left-dp(10);currentFrame=Math.max(0,Math.min(project.model.totalFrames-1,(int)((e.getX()-left)/w*project.model.totalFrames)));if(player!=null)player.seekTo((int)(currentFrame*1000L/project.model.fps));updatePosition();invalidate();return true;}return true;}}
 private void fullPreview(){Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar_Fullscreen);LinearLayout content=vertical();content.setBackgroundColor(bg);Preview full=new Preview();content.addView(full,new LinearLayout.LayoutParams(-1,0,1));content.addView(button("Close fullscreen",false,dialog::dismiss));dialog.setContentView(content);Runnable update=new Runnable(){public void run(){if(dialog.isShowing()){full.invalidate();handler.postDelayed(this,40);}}};dialog.setOnDismissListener(d->{handler.removeCallbacks(update);full.release();});dialog.show();handler.post(update);}
