 private void beginExport(Uri destination)throws Exception{pause();Project snapshot=new Project(new MediaFiles(this));snapshot.load(project.save().toString());snapshot.media.validate(snapshot.model,snapshot.narration);int[]size=snapshot.model.size(tier);ExportService.project=snapshot;ExportService.width=size[0];ExportService.height=size[1];ExportService.quality=quality;ExportService.destination=destination;if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},30);ExportService.phase="";ExportService.result=null;ExportService.percent=0;ExportService.started=System.currentTimeMillis();startForegroundService(new Intent(this,ExportService.class));showProgress();}
 private void showProgress(){progressHidden=false;if(progressDialog!=null&&progressDialog.isShowing())return;LinearLayout b=vertical();b.setPadding(dp(20),dp(16),dp(20),dp(16));progressText=text("Preparing export…",14,white);add(b,progressText,-2);progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));add(b,progress,30);add(b,button("Cancel export",false,()->ExportService.cancel.set(true)),44);add(b,button("Close panel • continues in background",false,()->{progressHidden=true;progressDialog.dismiss();progressDialog=null;}),44);progressDialog=new AlertDialog.Builder(this).setTitle("Export MP4").setView(b).create();progressDialog.setCanceledOnTouchOutside(false);progressDialog.show();updateProgress();}
 private void updateProgress(){if(progressDialog==null||!progressDialog.isShowing())return;progress.setProgress(ExportService.percent);long elapsed=ExportService.started==0?0:Math.max(0,System.currentTimeMillis()-ExportService.started);String estimate="";if(ExportService.running&&ExportService.percent>=15&&ExportService.percent<90)estimate=" • ~"+clock(elapsed/1000.0*(90-ExportService.percent)/(ExportService.percent-10))+" left";progressText.setText(ExportService.phase+" • "+ExportService.percent+"%\nElapsed "+clock(elapsed/1000.0)+estimate);if(!ExportService.running&&!ExportService.phase.isEmpty()){Dialog d=progressDialog;progressDialog=null;d.dismiss();if(!ExportService.error.isEmpty())failure(new Exception(ExportService.error));else if(ExportService.result!=null)new AlertDialog.Builder(this).setTitle("Export complete").setMessage("MP4 saved. Temporary export files have been removed.").setPositiveButton("Play",(a,b)->{try{startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(ExportService.result,"video/mp4").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){toast("Video saved. Open it in your Files app.");}}).setNeutralButton("Share",(a,b)->startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,ExportService.result).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share video"))).setNegativeButton("Done",null).show();else toast(ExportService.phase);}}
