 public void chooseRatio(String label){if(ExportService.running){toast("Wait for export or cancel it first.");return;}String value=label.startsWith("9:16")?"VERTICAL":label.startsWith("16:9")?"HORIZONTAL":label.startsWith("1:1")?"SQUARE":label.startsWith("4:5")?"PORTRAIT":"";try{if(value.isEmpty())project.overrides.remove("orientation");else project.overrides.put("orientation",value);if(!project.script.trim().isEmpty()){project.resolve();if(project.narration!=null&&!project.media.images.isEmpty())project.media.validate(project.model,project.narration);validation="✓ Canvas: "+project.model.aspect;}autosave();build();if(editor)prepareAudio(false);}catch(Exception e){project.model=null;failure(e);}}
 public void showValidation(Exception extra){if(overflowMenu!=null)overflowMenu.dismiss();SyncSupport.Report report=SyncSupport.validate(this,project.script);if(extra!=null){String message=extra.getMessage()==null?extra.toString():extra.getMessage();int colon=message.indexOf(':');String path=message.startsWith("$")&&colon>0?message.substring(0,colon):"$";report.add(path,"production_import",null,colon>0&&message.startsWith("$")?message.substring(colon+1).trim():message,"ERROR");}if(report.model!=null&&project.narration!=null&&!project.media.images.isEmpty())try{project.media.validate(report.model,project.narration);}catch(Exception e){String message=e.getMessage();int colon=message.indexOf(':');report.add(message.startsWith("$")&&colon>0?message.substring(0,colon):"$","media",null,colon>0?message.substring(colon+1).trim():message,"ERROR");}String message=report.copy();TextView text=text(message,12,white);text.setTextIsSelectable(true);text.setPadding(dp(14),dp(8),dp(14),dp(8));ScrollView scroll=new ScrollView(this);scroll.addView(text);validationDialog=new AlertDialog.Builder(this).setTitle("Validation • "+(report.valid()?"Ready": "Needs attention")).setView(scroll).setPositiveButton("Close",null).setNeutralButton("Copy errors for ChatGPT",(d,w)->{SyncSupport.copy(this,"ATS correction",message);toast("Diagnostics copied.");}).setNegativeButton(project.model==null?"Edit JSON":"Utilization",(d,w)->{if(project.model==null)paste();else showUtilization();}).show();}
